// Sound is generated locally: distant wind, a low heartbeat, and interaction cues.
let audio=null,master=null;function startAudio(){if(audio)return;audio=new (window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.18;master.connect(audio.destination);const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=47;gain.gain.value=.17;osc.connect(gain);gain.connect(master);osc.start();const lfo=audio.createOscillator(),lg=audio.createGain();lfo.frequency.value=.11;lg.gain.value=8;lfo.connect(lg);lg.connect(osc.frequency);lfo.start()}
